from scapy.all import *

# Load the pcapng file
packets = rdpcap('/home/ctfplayer/ctf_files/constela.pcapng')

# Extract and write out all transport payloads with marker and actual data
with open("/home/ctfplayer/analysis/extracted_data.txt", "w") as f:
    for packet in packets:
        if hasattr(packet, 'load'):
            data = bytes(packet.load).decode(errors='replace')
            if 'flag{' in data:
                f.write(data + "\n")
